fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Validate that j is within column bounds
    assert!(j < m, "Column index j must be less than m");
    
    // Build the column by collecting the j-th element from each row
    (0..n).map(|i| input[i][j]).collect()
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Validate input dimensions
    assert!(n > 0, "Matrix must have at least one row");
    assert!(m > 0, "Matrix must have at least one column");
    assert_eq!(input.len(), n, "Input must have exactly n rows");
    for row in &input {
        assert_eq!(row.len(), m, "Each row must have exactly m columns");
    }
    
    // Build the transposed matrix by collecting each column
    (0..m).map(|j| get_column(&input, j, m, n)).collect()
}